namespace sv_1471a1b91f6148fabc0d74ea780316e7.Services;

public record UserProfile(string DisplayName, string Email, string AvatarUrl, string Bio);
public record NotificationPrefs(bool EmailNotifications, bool PushNotifications, bool WeeklyDigest, List<string> MutedChannels);
public record SecuritySettings(bool TwoFactorEnabled, DateTime? LastPasswordChange, List<ActiveSession> Sessions);
public record ActiveSession(string Id, string Device, string Location, DateTime LastActive);
public record AppearanceSettings(string Theme, string FontSize, string Language, bool CompactMode);

public interface ISettingsService
{
    Task<UserProfile> GetProfileAsync();
    Task SaveProfileAsync(UserProfile profile);
    Task<NotificationPrefs> GetNotificationPrefsAsync();
    Task SaveNotificationPrefsAsync(NotificationPrefs prefs);
    Task<SecuritySettings> GetSecuritySettingsAsync();
    Task ChangePasswordAsync(string currentPassword, string newPassword);
    Task RevokeSessionAsync(string sessionId);
    Task<AppearanceSettings> GetAppearanceAsync();
    Task SaveAppearanceAsync(AppearanceSettings settings);
}

@page "/settings"
@using sv_1471a1b91f6148fabc0d74ea780316e7.Services
@inject ISettingsService SettingsService
@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-container">
    <nav class="settings-sidebar">
        <ul>
            <li class="@(activeSection == "Profile" ? "active" : "")" @onclick='() => SetSection("Profile")'>
                <span class="nav-icon">👤</span> Profile
            </li>
            <li class="@(activeSection == "Notifications" ? "active" : "")" @onclick='() => SetSection("Notifications")'>
                <span class="nav-icon">🔔</span> Notifications
            </li>
            <li class="@(activeSection == "Security" ? "active" : "")" @onclick='() => SetSection("Security")'>
                <span class="nav-icon">🔒</span> Security
            </li>
            <li class="@(activeSection == "Appearance" ? "active" : "")" @onclick='() => SetSection("Appearance")'>
                <span class="nav-icon">🎨</span> Appearance
            </li>
        </ul>
    </nav>

    <main class="settings-content">
        @if (isLoading)
        {
            <div class="loading">Loading settings...</div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile":
                    <ProfileSection />
                    break;
                case "Notifications":
                    <NotificationsSection />
                    break;
                case "Security":
                    <SecuritySection />
                    break;
                case "Appearance":
                    <AppearanceSection />
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(toastMessage))
        {
            <div class="toast @toastType">
                @toastMessage
            </div>
        }
    </main>
</div>

@* ===== Profile Section ===== *@
@{
    RenderFragment ProfileSection = __builder =>
    {
        <section class="settings-section">
            <h2>Profile</h2>

            <div class="avatar-preview">
                <img src="@editProfile.AvatarUrl" alt="Avatar" onerror="this.style.display='none'" />
                <p class="avatar-url">@editProfile.AvatarUrl</p>
            </div>

            <div class="form-group">
                <label for="displayName">Display Name</label>
                <input id="displayName" type="text" @bind="editProfile.DisplayName" />
            </div>

            <div class="form-group">
                <label for="email">Email</label>
                <input id="email" type="email" @bind="editProfile.Email" />
            </div>

            <div class="form-group">
                <label for="bio">Bio</label>
                <textarea id="bio" rows="4" @bind="editProfile.Bio"></textarea>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn-secondary" @onclick="DiscardProfileChanges">Discard Changes</button>
            </div>
        </section>
    };
}

@* ===== Notifications Section ===== *@
@{
    RenderFragment NotificationsSection = __builder =>
    {
        <section class="settings-section">
            <h2>Notifications</h2>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editNotifications.EmailNotifications" />
                    <span>Email Notifications</span>
                </label>

                <label class="toggle-label">
                    <input type="checkbox" @bind="editNotifications.PushNotifications" />
                    <span>Push Notifications</span>
                </label>

                <label class="toggle-label">
                    <input type="checkbox" @bind="editNotifications.WeeklyDigest" />
                    <span>Weekly Digest</span>
                </label>
            </div>

            <h3>Muted Channels</h3>
            <div class="channel-list">
                @foreach (var channel in availableChannels)
                {
                    var ch = channel;
                    <label class="toggle-label">
                        <input type="checkbox"
                               checked="@editNotifications.MutedChannels.Contains(ch)"
                               @onchange="(e) => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                        <span>@ch</span>
                    </label>
                }
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>
    };
}

@* ===== Security Section ===== *@
@{
    RenderFragment SecuritySection = __builder =>
    {
        <section class="settings-section">
            <h2>Security</h2>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => passwordPanelExpanded = !passwordPanelExpanded">
                    <span>Change Password</span>
                    <span class="expand-icon">@(passwordPanelExpanded ? "▾" : "▸")</span>
                </button>

                @if (passwordPanelExpanded)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label for="currentPassword">Current Password</label>
                            <input id="currentPassword" type="password" @bind="currentPassword" />
                        </div>
                        <div class="form-group">
                            <label for="newPassword">New Password</label>
                            <input id="newPassword" type="password" @bind="newPassword" />
                        </div>
                        <div class="form-group">
                            <label for="confirmPassword">Confirm Password</label>
                            <input id="confirmPassword" type="password" @bind="confirmPassword" />
                        </div>
                        <button class="btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="twofa-section">
                <h3>Two-Factor Authentication</h3>
                <div class="status-indicator">
                    <span class="status-dot @(securitySettings?.TwoFactorEnabled == true ? "enabled" : "disabled")"></span>
                    <span>@(securitySettings?.TwoFactorEnabled == true ? "Enabled" : "Disabled")</span>
                </div>
            </div>

            @if (securitySettings?.LastPasswordChange != null)
            {
                <p class="info-text">Last password change: @securitySettings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h3>Active Sessions</h3>
            <div class="sessions-table-wrapper">
                <table class="sessions-table">
                    <thead>
                        <tr>
                            <th>Device</th>
                            <th>Location</th>
                            <th>Last Active</th>
                            <th>Action</th>
                        </tr>
                    </thead>
                    <tbody>
                        @if (securitySettings?.Sessions != null)
                        {
                            @foreach (var session in securitySettings.Sessions)
                            {
                                <tr>
                                    <td>@session.Device</td>
                                    <td>@session.Location</td>
                                    <td>@session.LastActive.ToString("g")</td>
                                    <td>
                                        @if (session != securitySettings.Sessions.First())
                                        {
                                            <button class="btn-danger btn-small" @onclick="() => ConfirmRevokeSession(session)">Revoke</button>
                                        }
                                        else
                                        {
                                            <span class="current-badge">Current</span>
                                        }
                                    </td>
                                </tr>
                            }
                        }
                    </tbody>
                </table>
            </div>

            @if (showRevokeConfirmation)
            {
                <div class="modal-overlay" @onclick="CancelRevoke">
                    <div class="modal" @onclick:stopPropagation="true">
                        <h3>Confirm Session Revocation</h3>
                        <p>Are you sure you want to revoke the session on <strong>@sessionToRevoke?.Device</strong> in <strong>@sessionToRevoke?.Location</strong>?</p>
                        <div class="button-group">
                            <button class="btn-danger" @onclick="RevokeSession">Revoke Session</button>
                            <button class="btn-secondary" @onclick="CancelRevoke">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>
    };
}

@* ===== Appearance Section ===== *@
@{
    RenderFragment AppearanceSection = __builder =>
    {
        <section class="settings-section">
            <h2>Appearance</h2>

            <div class="form-group">
                <label>Theme</label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Light" checked="@(editAppearance.Theme == "Light")" @onchange='() => editAppearance.Theme = "Light"' />
                        <span>Light</span>
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="Dark" checked="@(editAppearance.Theme == "Dark")" @onchange='() => editAppearance.Theme = "Dark"' />
                        <span>Dark</span>
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="theme" value="System" checked="@(editAppearance.Theme == "System")" @onchange='() => editAppearance.Theme = "System"' />
                        <span>System</span>
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label>Font Size</label>
                <div class="radio-group">
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Small" checked="@(editAppearance.FontSize == "Small")" @onchange='() => editAppearance.FontSize = "Small"' />
                        <span>Small</span>
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Medium" checked="@(editAppearance.FontSize == "Medium")" @onchange='() => editAppearance.FontSize = "Medium"' />
                        <span>Medium</span>
                    </label>
                    <label class="radio-label">
                        <input type="radio" name="fontSize" value="Large" checked="@(editAppearance.FontSize == "Large")" @onchange='() => editAppearance.FontSize = "Large"' />
                        <span>Large</span>
                    </label>
                </div>
            </div>

            <div class="form-group">
                <label for="language">Language</label>
                <select id="language" @bind="editAppearance.Language">
                    <option value="en">English</option>
                    <option value="es">Spanish</option>
                    <option value="fr">French</option>
                    <option value="de">German</option>
                    <option value="ja">Japanese</option>
                    <option value="zh">Chinese</option>
                </select>
            </div>

            <div class="toggle-group">
                <label class="toggle-label">
                    <input type="checkbox" @bind="editAppearance.CompactMode" />
                    <span>Compact Mode</span>
                </label>
            </div>

            <div class="preview-area">
                <h4>Preview</h4>
                <div class="preview-box @GetPreviewClasses()">
                    <p class="preview-heading">Sample Heading</p>
                    <p>This is how your content will look with the selected appearance settings.</p>
                    <button class="preview-button">Sample Button</button>
                </div>
            </div>

            <div class="button-group">
                <button class="btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>
    };
}

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;

    // Toast
    private string? toastMessage;
    private string toastType = "success";
    private CancellationTokenSource? toastCts;

    // Profile
    private EditableProfile editProfile = new();
    private UserProfile? savedProfile;

    // Notifications
    private EditableNotifications editNotifications = new();
    private List<string> availableChannels = new() { "general", "announcements", "random", "support", "engineering" };

    // Security
    private SecuritySettings? securitySettings;
    private bool passwordPanelExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private bool showRevokeConfirmation;
    private ActiveSession? sessionToRevoke;

    // Appearance
    private EditableAppearance editAppearance = new();

    protected override async Task OnInitializedAsync()
    {
        await LoadAllSettings();
        isLoading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        savedProfile = profile;
        editProfile = new EditableProfile
        {
            DisplayName = profile.DisplayName,
            Email = profile.Email,
            AvatarUrl = profile.AvatarUrl,
            Bio = profile.Bio
        };

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        editNotifications = new EditableNotifications
        {
            EmailNotifications = notifs.EmailNotifications,
            PushNotifications = notifs.PushNotifications,
            WeeklyDigest = notifs.WeeklyDigest,
            MutedChannels = new List<string>(notifs.MutedChannels)
        };

        securitySettings = await SettingsService.GetSecuritySettingsAsync();

        var appearance = await SettingsService.GetAppearanceAsync();
        editAppearance = new EditableAppearance
        {
            Theme = appearance.Theme,
            FontSize = appearance.FontSize,
            Language = appearance.Language,
            CompactMode = appearance.CompactMode
        };
    }

    private void SetSection(string section)
    {
        activeSection = section;
    }

    // Profile methods
    private async Task SaveProfile()
    {
        var profile = new UserProfile(editProfile.DisplayName, editProfile.Email, editProfile.AvatarUrl, editProfile.Bio);
        await SettingsService.SaveProfileAsync(profile);
        savedProfile = profile;
        ShowToast("Profile saved successfully!", "success");
    }

    private void DiscardProfileChanges()
    {
        if (savedProfile != null)
        {
            editProfile = new EditableProfile
            {
                DisplayName = savedProfile.DisplayName,
                Email = savedProfile.Email,
                AvatarUrl = savedProfile.AvatarUrl,
                Bio = savedProfile.Bio
            };
        }
        ShowToast("Changes discarded.", "info");
    }

    // Notifications methods
    private void ToggleMutedChannel(string channel, bool isMuted)
    {
        if (isMuted && !editNotifications.MutedChannels.Contains(channel))
        {
            editNotifications.MutedChannels.Add(channel);
        }
        else if (!isMuted)
        {
            editNotifications.MutedChannels.Remove(channel);
        }
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(
            editNotifications.EmailNotifications,
            editNotifications.PushNotifications,
            editNotifications.WeeklyDigest,
            new List<string>(editNotifications.MutedChannels));
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved!", "success");
    }

    // Security methods
    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(currentPassword) || string.IsNullOrWhiteSpace(newPassword))
        {
            ShowToast("Please fill in all password fields.", "error");
            return;
        }

        if (newPassword != confirmPassword)
        {
            ShowToast("New password and confirmation do not match.", "error");
            return;
        }

        await SettingsService.ChangePasswordAsync(currentPassword, newPassword);
        currentPassword = "";
        newPassword = "";
        confirmPassword = "";
        passwordPanelExpanded = false;
        securitySettings = await SettingsService.GetSecuritySettingsAsync();
        ShowToast("Password updated successfully!", "success");
    }

    private void ConfirmRevokeSession(ActiveSession session)
    {
        sessionToRevoke = session;
        showRevokeConfirmation = true;
    }

    private async Task RevokeSession()
    {
        if (sessionToRevoke != null)
        {
            await SettingsService.RevokeSessionAsync(sessionToRevoke.Id);
            securitySettings = await SettingsService.GetSecuritySettingsAsync();
            ShowToast("Session revoked.", "success");
        }
        CancelRevoke();
    }

    private void CancelRevoke()
    {
        showRevokeConfirmation = false;
        sessionToRevoke = null;
    }

